// 纯计算函数；不访问账户、不获取外部数据. 与正文同一组教学设定.
function eventLedger(initialCash = 100, collectFirst = false) {
  if (!Number.isFinite(initialCash) || initialCash < 0) {
    throw new RangeError('期初现金必须为非负有限数');
  }
  if (typeof collectFirst !== 'boolean') {
    throw new TypeError('collectFirst必须为布尔值');
  }
  const s = {cash: initialCash, receivable: 0, inventory: 0,
             payable: 0, equity: initialCash, profit: 0, ocf: 0};
  const rows = [];
  const take = event => {
    const assets = s.cash + s.receivable + s.inventory;
    if (Math.abs(assets - s.payable - s.equity) > 1e-9) {
      throw new Error('资产负债关系不平');
    }
    rows.push({event, ...s, assets, balanceResidual: 0});
  };
  take('initial');
  s.inventory += 100; s.payable += 100; take('purchase');
  s.receivable += 150; s.inventory -= 100;
  s.equity += 50; s.profit += 50; take('sale');
  const order = collectFirst ? ['collect', 'pay'] : ['pay', 'collect'];
  for (const event of order) {
    if (event === 'pay') {
      if (s.cash < 100) return {rows, completed: false, fundingGap: 100 - s.cash};
      s.cash -= 100; s.payable -= 100; s.ocf -= 100;
    } else {
      s.cash += 150; s.receivable -= 150; s.ocf += 150;
    }
    take(event);
  }
  return {rows, completed: true, fundingGap: 0};
}

